const body = {
  model: 'gpt-6-luna',
  store: false,
  reasoning: { effort: 'none' },
  max_output_tokens: 500,
  instructions: 'Это техническая проверка OpenAI API. Классифицируй только синтетический запрос. Верни данные строго по JSON Schema.',
  input: 'Клиент спрашивает: «Какая гарантия на пластиковые окна?» База знаний нужна для ответа.',
  text: {
    format: {
      type: 'json_schema',
      name: 'pre02e_luna_guard',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          status: { type: 'string', enum: ['ok'] },
          klass: { type: 'string', enum: ['po_teme'] },
          nuzhen_poisk: { type: 'boolean' }
        },
        required: ['status', 'klass', 'nuzhen_poisk']
      }
    }
  }
};
return [{ json: { zapros_modeli: body } }];

const x = $json || {};
const texts = [];
for (const item of (x.output || [])) {
  if (item?.type !== 'message') continue;
  for (const c of (item.content || [])) {
    if (c?.type === 'output_text' && typeof c.text === 'string') texts.push(c.text);
  }
}
let parsed = null;
try { parsed = JSON.parse(texts.join('')); } catch {}
if (x.status !== 'completed' || !String(x.model || '').includes('gpt-6-luna')) {
  throw new Error('PRE-02E: GPT-6 Luna не завершил запрос ожидаемой моделью');
}
if (!parsed || parsed.status !== 'ok' || parsed.klass !== 'po_teme' || parsed.nuzhen_poisk !== true) {
  throw new Error('PRE-02E: Structured Output GPT-6 Luna не прошёл проверку');
}
const body = {
  model: 'gpt-6-sol',
  store: false,
  reasoning: { effort: 'low' },
  max_output_tokens: 1200,
  instructions: 'Это техническая проверка grounded-ответа. Используй только переданный факт. Верни данные строго по JSON Schema.',
  input: 'Факт из тестовой базы знаний: «Гарантия на пластиковые окна составляет 5 лет». Вопрос клиента: «Какой срок гарантии?»',
  text: {
    format: {
      type: 'json_schema',
      name: 'pre02e_sol_answer',
      strict: true,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          status: { type: 'string', enum: ['ok'] },
          mozhno_otvetit: { type: 'boolean' },
          otvet: { type: 'string' }
        },
        required: ['status', 'mozhno_otvetit', 'otvet']
      }
    }
  }
};
return [{
  json: {
    luna_status: 'verified',
    luna_model: x.model,
    luna_usage: x.usage || null,
    zapros_modeli: body
  }
}];

const x = $json || {};
const texts = [];
for (const item of (x.output || [])) {
  if (item?.type !== 'message') continue;
  for (const c of (item.content || [])) {
    if (c?.type === 'output_text' && typeof c.text === 'string') texts.push(c.text);
  }
}
let parsed = null;
try { parsed = JSON.parse(texts.join('')); } catch {}
if (x.status !== 'completed' || !String(x.model || '').includes('gpt-6-sol')) {
  throw new Error('PRE-02E: GPT-6 Sol не завершил запрос ожидаемой моделью');
}
const grounded = parsed && parsed.status === 'ok' && parsed.mozhno_otvetit === true &&
  typeof parsed.otvet === 'string' && /5\s*(лет|года|год)/i.test(parsed.otvet);
if (!grounded) {
  throw new Error('PRE-02E: grounded Structured Output GPT-6 Sol не прошёл проверку');
}
const body = {
  model: 'text-embedding-3-large',
  input: 'Пластиковые окна имеют гарантию пять лет. Монтаж выполняется после согласования заказа.',
  dimensions: 1024,
  encoding_format: 'float'
};
return [{
  json: {
    sol_status: 'verified',
    sol_model: x.model,
    sol_usage: x.usage || null,
    sol_answer: parsed.otvet,
    zapros_embedding: body
  }
}];

const x = $json || {};
const v = x.data?.[0]?.embedding;
if (x.model !== 'text-embedding-3-large' || !Array.isArray(v) || v.length !== 1024 || !v.every(Number.isFinite)) {
  throw new Error('PRE-02E: document embedding не равен 1024 конечным числам ожидаемой модели');
}
const body = {
  model: 'text-embedding-3-large',
  input: 'Сколько лет действует гарантия на окна?',
  dimensions: 1024,
  encoding_format: 'float'
};
return [{
  json: {
    document_embedding_status: 'verified',
    document_model: x.model,
    document_dimensions: v.length,
    document_usage: x.usage || null,
    document_embedding: v,
    zapros_embedding: body
  }
}];

const x = $json || {};
const q = x.data?.[0]?.embedding;
if (x.model !== 'text-embedding-3-large' || !Array.isArray(q) || q.length !== 1024 || !q.every(Number.isFinite)) {
  throw new Error('PRE-02E: query embedding не равен 1024 конечным числам ожидаемой модели');
}
const doc = $('Проверить embedding документа').first().json;
const d = doc.document_embedding;
if (!Array.isArray(d) || d.length !== 1024) {
  throw new Error('PRE-02E: не найден проверенный document embedding');
}
let dot = 0, na = 0, nb = 0;
for (let i = 0; i < 1024; i++) {
  dot += d[i] * q[i];
  na += d[i] * d[i];
  nb += q[i] * q[i];
}
const cosine = (na > 0 && nb > 0) ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : null;
const luna = $('Проверить GPT-6 Luna').first().json;
const sol = $('Проверить GPT-6 Sol').first().json;
return [{
  json: {
    pre02e_status: 'runtime_verified',
    expected_n8n_version: '2.41.0',
    llm_guard_planner_model: 'gpt-6-luna',
    llm_answer_model: 'gpt-6-sol',
    embedding_model: 'text-embedding-3-large',
    embedding_dimensions: 1024,
    luna_structured_output_ok: luna.luna_status === 'verified',
    sol_structured_output_ok: sol.sol_status === 'verified',
    document_embedding_ok: doc.document_embedding_status === 'verified',
    query_embedding_ok: true,
    cosine_similarity_informational: cosine,
    note: 'Cosine similarity здесь только диагностическая величина; retrieval threshold выбирается отдельно в PRE-02D.',
    usage: {
      luna: luna.luna_usage || null,
      sol: sol.sol_usage || null,
      document_embedding: doc.document_usage || null,
      query_embedding: x.usage || null
    }
  }
}];
